select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5139,"materia":"enf","nivel":0,"enunciado":"As vacinas devem ser conservadas, na rede de frio, entre:","opcoes":["+2 °C e +8 °C","−20 °C e −10 °C","+15 °C e +25 °C","+30 °C e +40 °C"],"explicacao":"A temperatura é conferida e registrada várias vezes ao dia."},{"id":5140,"materia":"enf","nivel":0,"enunciado":"A diurese abaixo de 400 mL em 24 horas, em adulto, é chamada de:","opcoes":["Oligúria","Poliúria","Disúria","Hematúria"],"explicacao":"Abaixo de 100 mL em 24 horas: anúria."},{"id":5141,"materia":"enf","nivel":0,"enunciado":"Bexiga palpável e dolorosa acima do púbis, sem conseguir urinar, sugere:","opcoes":["Retenção urinária (globo vesical)","Incontinência urinária de esforço","Infecção de pele","Diarreia"],"explicacao":"Pode exigir cateterismo vesical, conforme prescrição."},{"id":5142,"materia":"enf","nivel":0,"enunciado":"O colírio deve ser instilado:","opcoes":["No saco conjuntival inferior, sem encostar o frasco no olho","Diretamente sobre a córnea, com o frasco encostado no olho para não desperdiçar","No canto interno do olho fechado","Na pálpebra superior"],"explicacao":"Depois, pedir para fechar os olhos suavemente."},{"id":5143,"materia":"enf","nivel":0,"enunciado":"Para aplicar gotas no ouvido de um adulto, o pavilhão auricular deve ser puxado:","opcoes":["Para cima e para trás","Para baixo e para a frente","Para baixo e para trás","Não precisa puxar"],"explicacao":"Em crianças pequenas, para baixo e para trás."},{"id":5144,"materia":"enf","nivel":0,"enunciado":"O balonete (cuff) da sonda vesical de demora deve ser insuflado com:","opcoes":["Água destilada, no volume indicado pelo fabricante","Ar comprimido","Álcool a 70%","Soro glicosado a 5%, em qualquer volume disponível no setor"],"explicacao":"Soro fisiológico pode cristalizar e dificultar a retirada."},{"id":5145,"materia":"enf","nivel":0,"enunciado":"A posição ginecológica, usada no exame especular, é a:","opcoes":["Litotomia","Trendelenburg","Fowler","Prona"],"explicacao":"A paciente fica deitada, com pernas flexionadas e afastadas."},{"id":5146,"materia":"enf","nivel":0,"enunciado":"A ferida cirúrgica com bordas aproximadas por sutura cicatriza por:","opcoes":["Primeira intenção","Segunda intenção","Terceira intenção","Granulação aberta obrigatória"],"explicacao":"Na segunda intenção, a ferida fica aberta e se fecha aos poucos."},{"id":5147,"materia":"enf","nivel":0,"enunciado":"No pré-natal, a frequência cardíaca fetal normal fica entre:","opcoes":["110 e 160 batimentos por minuto","60 e 80 batimentos por minuto","200 e 250 batimentos por minuto","30 e 50 batimentos por minuto"],"explicacao":"Avaliada com sonar Doppler."},{"id":5148,"materia":"enf","nivel":0,"enunciado":"Na gestação, são sinais de alerta que exigem procurar o serviço:","opcoes":["Sangramento vaginal, perda de líquido e dor de cabeça forte com visão turva","Desejo por certos alimentos","Leve inchaço nos pés no fim do dia e vontade de comer alimentos específicos","Aumento do apetite"],"explicacao":"Também redução dos movimentos do bebê."},{"id":5149,"materia":"enf","nivel":0,"enunciado":"A vacina meningocócica C, no calendário infantil, é aplicada aos:","opcoes":["3 e 5 meses, com reforço aos 12 meses","Aos 15 anos apenas, em dose única, na escola","Ao nascer","10 e 20 anos"],"explicacao":"Protege contra a meningite meningocócica do sorogrupo C."},{"id":5150,"materia":"enf","nivel":0,"enunciado":"A vacina pneumocócica conjugada, no calendário infantil, é aplicada aos:","opcoes":["2 e 4 meses, com reforço aos 12 meses","9 e 15 anos","Ao nascer","Aos 60 anos apenas, em dose única, na campanha"],"explicacao":"Protege contra pneumonia, otite e meningite pneumocócicas."},{"id":5151,"materia":"enf","nivel":0,"enunciado":"A vacina contra hepatite A, no calendário infantil, é aplicada aos:","opcoes":["15 meses","2 meses","10 anos","Ao nascer"],"explicacao":"Dose única no calendário de rotina."},{"id":5152,"materia":"enf","nivel":0,"enunciado":"Vacinas de vírus vivos atenuados, como a tríplice viral, em geral:","opcoes":["Não são aplicadas em gestantes","São obrigatórias no 1º trimestre","Substituem o pré-natal","Só podem ser aplicadas em gestantes"],"explicacao":"A mulher deve evitar engravidar por 30 dias após a tríplice viral."},{"id":5153,"materia":"enf","nivel":0,"enunciado":"Na punção venosa, o garrote deve ficar apertado por no máximo cerca de:","opcoes":["1 minuto","15 minutos","30 minutos","1 hora"],"explicacao":"Garrote prolongado altera resultados de exames."},{"id":5154,"materia":"enf","nivel":0,"enunciado":"Diante de uma prescrição ilegível, o profissional de enfermagem deve:","opcoes":["Não executar e pedir esclarecimento ao prescritor","Adivinhar o que está escrito","Dar a dose que costuma ser usada para aquele remédio na unidade","Perguntar a outro paciente"],"explicacao":"A segurança do paciente vem primeiro."},{"id":5155,"materia":"enf","nivel":0,"enunciado":"Ao errar uma anotação no prontuário de papel, o profissional deve:","opcoes":["Riscar com um traço, mantendo o texto legível, e escrever a correção","Usar corretivo","Rasgar a folha","Usar corretivo líquido, cobrir o erro por completo e escrever a informação certa por cima"],"explicacao":"O prontuário é documento legal."},{"id":5156,"materia":"enf","nivel":0,"enunciado":"A técnica em Z, na injeção intramuscular, serve para:","opcoes":["Evitar o refluxo do medicamento para o tecido subcutâneo","Aumentar a dor","Acelerar a absorção do medicamento e permitir aplicar volumes maiores no mesmo local","Dispensar a antissepsia"],"explicacao":"Indicada para medicamentos irritantes, como o ferro."},{"id":5157,"materia":"enf","nivel":0,"enunciado":"A bronquiolite em bebês é causada principalmente pelo:","opcoes":["Vírus sincicial respiratório (VSR)","Bacilo da tuberculose (bacilo de Koch)","Vírus da hepatite A","Fungo da candidíase"],"explicacao":"Mais comum no outono e no inverno."},{"id":5158,"materia":"enf","nivel":1,"enunciado":"No pré-natal de risco habitual, as consultas costumam ser:","opcoes":["Mensais até 28 semanas, quinzenais até 36 e semanais depois","Uma única vez na gestação, perto da data provável do parto, se houver queixa","Semanais desde o início","Só no último mês"],"explicacao":"Segundo o Ministério da Saúde."},{"id":5159,"materia":"enf","nivel":1,"enunciado":"Os testes rápidos de HIV e sífilis no pré-natal devem ser feitos:","opcoes":["Na primeira consulta e no terceiro trimestre","Só no parto","Apenas se a gestante pedir por escrito ao médico do pré-natal","Somente no pós-parto"],"explicacao":"Também no parto ou em situações de exposição de risco."},{"id":5160,"materia":"enf","nivel":1,"enunciado":"O rastreamento do diabetes gestacional com teste oral de tolerância à glicose costuma ser feito entre:","opcoes":["24 e 28 semanas","4 e 8 semanas","38 e 40 semanas","Após o parto"],"explicacao":"Quando a glicemia de jejum inicial está normal."},{"id":5161,"materia":"enf","nivel":1,"enunciado":"As manobras de Leopold servem para identificar:","opcoes":["A posição e a apresentação do feto no útero","A pressão arterial da mãe durante o trabalho de parto","O tipo sanguíneo do bebê","A glicemia materna"],"explicacao":"Feitas pela palpação do abdome."},{"id":5162,"materia":"enf","nivel":1,"enunciado":"A escala de Katz avalia, no idoso:","opcoes":["A independência nas atividades básicas de vida diária","A memória","A visão","A pressão arterial em repouso e depois de caminhar"],"explicacao":"Banho, vestir-se, usar o banheiro, transferir-se, continência e alimentação."},{"id":5163,"materia":"enf","nivel":1,"enunciado":"A escala de Lawton avalia:","opcoes":["As atividades instrumentais de vida diária, como usar telefone e controlar o dinheiro","Somente a força muscular dos braços e das pernas, sem considerar tarefas do dia a dia","A dor","O sono"],"explicacao":"Mostra a capacidade de viver de forma independente."},{"id":5164,"materia":"enf","nivel":1,"enunciado":"Pela Lei nº 10.216/2001, a internação psiquiátrica involuntária deve ser comunicada ao Ministério Público em até:","opcoes":["72 horas","30 dias","1 ano","Não precisa comunicar"],"explicacao":"O mesmo vale para a alta."},{"id":5165,"materia":"enf","nivel":1,"enunciado":"O cateterismo vesical intermitente consiste em:","opcoes":["Introduzir a sonda para esvaziar a bexiga e retirá-la em seguida","Manter a sonda por meses","Lavar a bexiga com álcool diluído todos os dias para evitar infecção","Medir a pressão da bexiga"],"explicacao":"Muito usado em pessoas com bexiga neurogênica."},{"id":5166,"materia":"enf","nivel":1,"enunciado":"A posição genupeitoral é usada, por exemplo, em:","opcoes":["Exames retais e alguns procedimentos","Parto normal","Ventilação mecânica em pacientes na UTI","Banho no leito"],"explicacao":"A pessoa fica ajoelhada, com o peito apoiado na cama."},{"id":5167,"materia":"enf","nivel":1,"enunciado":"Na desnutrição grave do tipo kwashiorkor, é característico:","opcoes":["Edema, principalmente nas pernas, com alterações de pele e cabelo","Obesidade","Pele normal, cabelo sem nenhuma alteração e ganho de peso rápido nas pernas","Aumento da altura"],"explicacao":"No marasmo, predomina a perda de gordura e músculo, sem edema."},{"id":5168,"materia":"enf","nivel":1,"enunciado":"Em bebê com menos de 3 meses, a febre deve ser:","opcoes":["Avaliada com atenção, pois pode indicar infecção grave","Tratada sempre em casa, com antitérmico e sem avaliação","Ignorada","Tratada só com banho frio"],"explicacao":"Bebês pequenos têm mais risco de infecções graves."},{"id":5169,"materia":"enf","nivel":1,"enunciado":"No termômetro da caixa de vacinas, a leitura das temperaturas máxima e mínima serve para:","opcoes":["Saber se as vacinas ficaram fora da faixa adequada","Medir a febre das crianças antes da vacinação na sala","Controlar a umidade","Decorar a sala"],"explicacao":"Alterações devem ser comunicadas antes de usar as vacinas."},{"id":5170,"materia":"enf","nivel":1,"enunciado":"No adulto, o volume de urina considerado adequado é de cerca de:","opcoes":["0,5 a 1 mL/kg por hora","10 mL/kg por hora","0,01 a 0,05 mL/kg por hora","5 litros por hora"],"explicacao":"Valores menores podem indicar desidratação ou lesão renal."},{"id":5171,"materia":"enf","nivel":2,"enunciado":"Na gestante com sangramento vaginal no terceiro trimestre, não se deve fazer:","opcoes":["Toque vaginal antes de afastar placenta prévia","Avaliação dos sinais vitais","Ausculta dos batimentos fetais","Encaminhamento ao serviço de referência para avaliação"],"explicacao":"O toque pode agravar o sangramento."},{"id":5172,"materia":"enf","nivel":2,"enunciado":"Na hemorragia pós-parto, a principal causa é:","opcoes":["Atonia uterina (útero que não contrai)","Excesso de leite","Febre baixa","Hipertensão crônica controlada com remédio"],"explicacao":"A ocitocina é usada na prevenção logo após o parto."},{"id":5173,"materia":"enf","nivel":2,"enunciado":"No recém-nascido, a respiração com gemido, batimento de asa do nariz e tiragem indica:","opcoes":["Desconforto respiratório","Sono tranquilo","Fome apenas","Calor excessivo, sem gravidade"],"explicacao":"Precisa de avaliação imediata."},{"id":5174,"materia":"enf","nivel":2,"enunciado":"Para o idoso acamado, a prevenção de broncoaspiração inclui:","opcoes":["Manter a cabeceira elevada durante e após a alimentação","Alimentar deitado reto","Dar líquidos rapidamente","Deixar o paciente sozinho e deitado reto para comer no próprio ritmo"],"explicacao":"Também adaptar a consistência dos alimentos, se necessário."},{"id":5175,"materia":"enf","nivel":2,"enunciado":"Em uma ferida com sinais de infecção, espera-se encontrar:","opcoes":["Vermelhidão ao redor, calor, dor aumentada e secreção purulenta","Tecido vermelho vivo sem dor","Pele íntegra ao redor","Bordas se fechando, sem secreção, com tecido rosado e sem dor ao redor"],"explicacao":"Febre pode acompanhar."},{"id":5176,"materia":"enf","nivel":2,"enunciado":"Na intoxicação por organofosforados (agrotóxicos), são sinais típicos:","opcoes":["Pupilas puntiformes, salivação excessiva, suor e bradicardia","Pupilas dilatadas, pele seca e quente, boca seca e taquicardia","Febre alta isolada","Coceira sem outros sinais"],"explicacao":"O antídoto usado é a atropina."},{"id":5177,"materia":"enf","nivel":2,"enunciado":"Em uma criança engasgada, consciente e que não consegue tossir nem falar, a conduta é:","opcoes":["Manobra de Heimlich (compressões abdominais), em maiores de 1 ano","Oferecer água","Bater nas costas com a criança em pé, sem parar, até ela começar a chorar","Esperar passar"],"explicacao":"Em bebês menores de 1 ano: golpes nas costas e compressões no tórax."},{"id":5178,"materia":"enf","nivel":2,"enunciado":"Após o parto, a mulher deve ser orientada a voltar para consulta de puerpério:","opcoes":["Na primeira semana e até 42 dias após o parto","Só depois de 1 ano","Apenas se tiver febre alta ou sangramento intenso depois do parto","Não é necessário"],"explicacao":"Avalia a recuperação, a amamentação e o planejamento familiar."},{"id":5179,"materia":"enf","nivel":3,"enunciado":"Uma criança de 8 kg com diarreia e algum grau de desidratação (Plano B) deve receber, em cerca de 4 horas, SRO no volume de:","opcoes":["50 a 100 mL/kg, ou seja, 400 a 800 mL","10 mL no total","2 litros","Nenhum volume de SRO, apenas leite materno ou fórmula"],"explicacao":"O Plano B é feito na unidade de saúde, com reavaliação."},{"id":5180,"materia":"enf","nivel":3,"enunciado":"Na criança com desidratação grave (Plano C), a hidratação é feita:","opcoes":["Por via venosa, no serviço de saúde","Em casa, com chá","Só com SRO em pequenos goles, em casa","Apenas com leite materno"],"explicacao":"É uma urgência."},{"id":5181,"materia":"enf","nivel":3,"enunciado":"No uso de sulfato de magnésio, a equipe deve vigiar sinais de intoxicação, como:","opcoes":["Perda do reflexo patelar, respiração lenta e pouca urina","Aumento da pressão arterial, dor de cabeça forte e aumento da urina","Febre","Coceira leve"],"explicacao":"Antídoto: gluconato de cálcio."},{"id":5182,"materia":"enf","nivel":3,"enunciado":"A escala de dor FLACC é usada em:","opcoes":["Crianças pequenas ou pessoas que não conseguem relatar a dor","Adultos que falam normalmente e conseguem dar uma nota de 0 a 10 à dor","Avaliação da visão","Medida da temperatura"],"explicacao":"Avalia face, pernas, atividade, choro e consolabilidade."},{"id":5183,"materia":"enf","nivel":4,"enunciado":"Prescrição: 200 mg de hidrocortisona. O frasco tem 500 mg, a ser diluído em 4 mL. Devem ser aspirados:","opcoes":["1,6 mL","2 mL","0,8 mL","4 mL"],"explicacao":"500 mg em 4 mL = 125 mg/mL; 200 ÷ 125 = 1,6."},{"id":5184,"materia":"enf","nivel":4,"enunciado":"Em adulto, a dopamina 250 mg em 250 mL de soro corre a 18 mL/h. A dose em mg por hora é:","opcoes":["18 mg/h","1,8 mg/h","180 mg/h","4,5 mg/h"],"explicacao":"A concentração é de 1 mg/mL."},{"id":5185,"materia":"enf","nivel":4,"enunciado":"Na gestante Rh negativo com parceiro Rh positivo, a imunoglobulina anti-D é indicada:","opcoes":["Por volta de 28 semanas e até 72 horas após o parto de bebê Rh positivo, entre outras situações","Apenas aos 5 anos da criança, junto com as vacinas de reforço do calendário, e nunca na gestação","Nunca durante a gestação","Somente se a mãe tiver febre"],"explicacao":"Previne a sensibilização materna e a doença hemolítica em futuras gestações."},{"id":5186,"materia":"enf","nivel":4,"enunciado":"Na RCP de um lactente feita por dois socorristas, a relação entre compressões e ventilações é de:","opcoes":["15:2","30:2","5:1","50:2"],"explicacao":"Com um único socorrista, a relação é 30:2."},{"id":5187,"materia":"sus","nivel":0,"enunciado":"Pela Lei nº 8.080/1990, são fatores determinantes e condicionantes da saúde, entre outros:","opcoes":["Alimentação, moradia, saneamento básico, trabalho, renda e educação","Apenas a herança genética","Somente o número de hospitais, de leitos e de médicos especialistas disponíveis","Só o clima da região"],"explicacao":"Art. 3º."},{"id":5188,"materia":"sus","nivel":0,"enunciado":"A transferência de recursos do Fundo Nacional de Saúde para os fundos estaduais e municipais é chamada de:","opcoes":["Transferência fundo a fundo","Empréstimo bancário","Doação de empresas","Pagamento por boleto do usuário"],"explicacao":"Dispensa convênios para o repasse regular."},{"id":5189,"materia":"sus","nivel":0,"enunciado":"A Política Nacional de Atenção Integral à Saúde da Mulher (PNAISM) foi lançada em:","opcoes":["2004","1960","2020","1888"],"explicacao":"Amplia o cuidado além do ciclo gravídico-puerperal."},{"id":5190,"materia":"sus","nivel":0,"enunciado":"A Política Nacional de Saúde da Pessoa Idosa tem como uma de suas diretrizes:","opcoes":["Promover o envelhecimento ativo e saudável","Internar todos os idosos","Proibir idosos de trabalhar","Reduzir as consultas para idosos e priorizar internações"],"explicacao":"Busca manter a autonomia e a independência."},{"id":5191,"materia":"sus","nivel":0,"enunciado":"O acesso de imigrantes e refugiados aos serviços do SUS:","opcoes":["É garantido, independentemente da situação migratória","É proibido","Só vale para quem tem passaporte europeu ou visto permanente","Exige pagamento prévio"],"explicacao":"A saúde é direito de todos que estão no território nacional."},{"id":5192,"materia":"sus","nivel":0,"enunciado":"A PNAISC, política nacional voltada à saúde da criança, tem entre seus eixos:","opcoes":["Aleitamento materno e alimentação complementar saudável","A venda de fórmulas infantis nas unidades básicas de saúde","O fim da puericultura","A proibição de vacinas"],"explicacao":"Também crescimento e desenvolvimento e prevenção de violências."},{"id":5193,"materia":"sus","nivel":0,"enunciado":"Os Agentes de Combate às Endemias atuam principalmente:","opcoes":["Na prevenção e no controle de doenças como dengue, por meio de visitas e eliminação de criadouros","Na realização de cirurgias","Na prescrição de antibióticos e de outros remédios para a população com sintomas de infecção nas visitas domiciliares","No atendimento de partos"],"explicacao":"Trabalham em conjunto com os ACS."},{"id":5194,"materia":"sus","nivel":1,"enunciado":"A Portaria GM/MS nº 3.493/2024 trata:","opcoes":["Do novo modelo de cofinanciamento federal da Atenção Primária à Saúde","Do calendário de vacinação infantil e das campanhas de multivacinação","Do Código de Ética Médica","Da criação do SUS"],"explicacao":"Substituiu o modelo de financiamento anterior da APS."},{"id":5195,"materia":"sus","nivel":1,"enunciado":"Desde 2018 (Portaria nº 3.992/2017), os repasses federais para custeio e investimento no SUS são organizados em:","opcoes":["Dois blocos: custeio e investimento","Doze blocos fixos","Um único repasse anual em dinheiro vivo","Convênios com cada hospital"],"explicacao":"Antes havia seis blocos de financiamento."},{"id":5196,"materia":"sus","nivel":1,"enunciado":"Na vigilância epidemiológica, a investigação de um caso notificado busca:","opcoes":["Identificar a fonte, os contatos e as medidas de controle","Punir o paciente","Cobrar o tratamento","Divulgar o nome do paciente para alertar os vizinhos e a escola"],"explicacao":"Respeitando o sigilo das informações."},{"id":5197,"materia":"sus","nivel":1,"enunciado":"O bloqueio vacinal, feito após um caso de sarampo, consiste em:","opcoes":["Vacinar os contatos suscetíveis do caso, rapidamente","Fechar a cidade","Isolar toda a escola e o bairro por um ano letivo inteiro","Vacinar apenas o doente"],"explicacao":"Interrompe a cadeia de transmissão."},{"id":5198,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Atenção à Saúde dos Povos Indígenas é organizada por meio dos:","opcoes":["Distritos Sanitários Especiais Indígenas (DSEI)","Hospitais universitários das capitais estaduais","Consórcios de municípios","Planos de saúde privados"],"explicacao":"Respeitando as culturas e os territórios indígenas."},{"id":5199,"materia":"sus","nivel":2,"enunciado":"Na atenção ao adolescente em conflito com a lei, a PNAISARI garante:","opcoes":["Atendimento em saúde aos adolescentes em medidas socioeducativas","Apenas atendimento após os 18 anos","Atendimento só por médicos particulares pagos pelas famílias dos adolescentes","Nenhum atendimento"],"explicacao":"Integra esses adolescentes à rede do SUS."},{"id":5200,"materia":"sus","nivel":2,"enunciado":"A Rede de Atenção Psicossocial (RAPS) inclui, entre seus pontos de atenção:","opcoes":["CAPS, unidades básicas, leitos em hospital geral e serviços residenciais terapêuticos","Somente manicômios","Apenas consultórios particulares de psiquiatria e psicologia conveniados aos planos de saúde","Somente presídios"],"explicacao":"Organiza o cuidado em saúde mental no território."},{"id":5201,"materia":"sus","nivel":2,"enunciado":"O Serviço Residencial Terapêutico é uma moradia para:","opcoes":["Pessoas egressas de longas internações psiquiátricas","Turistas","Estudantes de medicina","Profissionais de saúde em plantão noturno nos hospitais"],"explicacao":"Favorece a reinserção social."},{"id":5202,"materia":"sus","nivel":3,"enunciado":"A vigilância em saúde ambiental acompanha, entre outros riscos:","opcoes":["Contaminação da água, do ar e do solo, e desastres","Somente a inflação","Apenas o trânsito","Somente o preço dos alimentos nos mercados e nas feiras"],"explicacao":"Ex.: VIGIAGUA e VIGIAR."},{"id":5203,"materia":"sus","nivel":3,"enunciado":"A Política Nacional de Saúde do Trabalhador e da Trabalhadora (2012) prevê:","opcoes":["A atenção integral à saúde do trabalhador, com ênfase na vigilância","Apenas o pagamento de seguro","A demissão de trabalhadores doentes para reduzir os custos das empresas","O fim das CATs"],"explicacao":"Inclui trabalhadores formais e informais."},{"id":5204,"materia":"sus","nivel":3,"enunciado":"O Programa Nacional de Controle da Tuberculose prioriza, entre outras ações:","opcoes":["Busca ativa de casos, tratamento diretamente observado e investigação de contatos","Internação de todos os casos","Isolamento domiciliar por anos","Tratamento só em hospitais privados, com internação obrigatória de todos os casos"],"explicacao":"A cura interrompe a transmissão."},{"id":5205,"materia":"sus","nivel":4,"enunciado":"Pela Lei nº 8.080/1990, a direção do SUS no âmbito dos municípios é exercida:","opcoes":["Pela respectiva Secretaria de Saúde ou órgão equivalente","Pelo Ministério da Saúde diretamente, sem participação local","Pelos hospitais privados","Pela Câmara de Vereadores"],"explicacao":"No âmbito da União, pelo Ministério da Saúde; nos estados, pelas secretarias estaduais."},{"id":5206,"materia":"sus","nivel":4,"enunciado":"A Lei nº 8.080/1990 permite que os municípios constituam consórcios para:","opcoes":["Desenvolver em conjunto as ações e os serviços de saúde que lhes correspondam","Vender serviços de saúde a outros países e a empresas estrangeiras com lucro","Criar planos de saúde privados","Substituir o Ministério da Saúde"],"explicacao":"Art. 10."},{"id":5207,"materia":"med","nivel":0,"enunciado":"A obesidade, em adultos, é definida por IMC igual ou maior que:","opcoes":["30 kg/m²","20 kg/m²","25 kg/m²","40 kg/m²"],"explicacao":"Entre 25 e 29,9 é sobrepeso."},{"id":5208,"materia":"med","nivel":0,"enunciado":"As estatinas são usadas principalmente para:","opcoes":["Reduzir o colesterol LDL e o risco cardiovascular","Baixar a glicemia de jejum e a hemoglobina glicada","Tratar infecções","Aliviar a dor"],"explicacao":"Ex.: sinvastatina e atorvastatina."},{"id":5209,"materia":"med","nivel":0,"enunciado":"A erisipela é uma infecção de pele que costuma ter:","opcoes":["Bordas bem delimitadas e elevadas, com vermelhidão intensa","Bolhas pequenas em cachos, sempre ao longo de um nervo do tronco","Manchas brancas sem dor","Coceira sem vermelhidão"],"explicacao":"Geralmente causada por estreptococo."},{"id":5210,"materia":"med","nivel":0,"enunciado":"Febre alta, dor lombar e sinal de Giordano positivo sugerem:","opcoes":["Pielonefrite","Cistite simples","Apendicite","Gastrite"],"explicacao":"Infecção urinária alta."},{"id":5211,"materia":"med","nivel":0,"enunciado":"O consentimento livre e esclarecido exige que o paciente:","opcoes":["Receba informações claras e decida livremente sobre o procedimento","Assine sem ler","Seja pressionado a aceitar o que o médico decidir, sem tirar dúvidas","Não faça perguntas"],"explicacao":"É base do respeito à autonomia."},{"id":5212,"materia":"med","nivel":0,"enunciado":"A densitometria óssea é usada para diagnosticar:","opcoes":["Osteoporose","Diabetes","Hipertensão","Anemia"],"explicacao":"Mede a densidade mineral óssea."},{"id":5213,"materia":"med","nivel":1,"enunciado":"No AVC agudo, o primeiro exame de imagem para diferenciar isquemia de hemorragia é a:","opcoes":["Tomografia de crânio sem contraste","Radiografia simples de tórax","Ultrassom de abdome","Endoscopia"],"explicacao":"A hemorragia aparece logo na tomografia."},{"id":5214,"materia":"med","nivel":1,"enunciado":"As sulfonilureias, como a glibenclamida, têm como risco importante:","opcoes":["Hipoglicemia","Hipertensão arterial","Febre","Tosse seca"],"explicacao":"Especialmente em idosos."},{"id":5215,"materia":"med","nivel":1,"enunciado":"A síndrome metabólica inclui, entre seus componentes:","opcoes":["Obesidade abdominal, pressão alta, glicemia elevada e alterações no colesterol e triglicerídeos","Apenas febre","Somente anemia","Apenas dor nas costas e cansaço ao fim do dia, sem nenhuma alteração em exames de sangue"],"explicacao":"Aumenta o risco cardiovascular."},{"id":5216,"materia":"med","nivel":1,"enunciado":"Na doença falciforme, um medicamento que reduz as crises de dor é a:","opcoes":["Hidroxiureia","Insulina","Amoxicilina","Levotiroxina"],"explicacao":"Disponível no SUS, conforme protocolo."},{"id":5217,"materia":"med","nivel":1,"enunciado":"Na uretrite gonocócica, o tratamento recomendado no Brasil inclui:","opcoes":["Ceftriaxona associada à azitromicina","Apenas antifúngico em creme na região","Somente analgésico","Nenhum tratamento"],"explicacao":"As parcerias sexuais também devem ser tratadas."},{"id":5218,"materia":"med","nivel":2,"enunciado":"A tosse seca é um efeito colateral comum dos:","opcoes":["Inibidores da ECA, como enalapril e captopril","Diuréticos tiazídicos","Bloqueadores de canal de cálcio, como o anlodipino","Betabloqueadores"],"explicacao":"Nesse caso, pode-se trocar por um BRA."},{"id":5219,"materia":"med","nivel":2,"enunciado":"O edema de tornozelos é um efeito colateral comum da:","opcoes":["Anlodipino","Metformina","Losartana","Hidroclorotiazida"],"explicacao":"É um bloqueador de canal de cálcio."},{"id":5220,"materia":"med","nivel":3,"enunciado":"Em paciente com fibrilação atrial, o escore CHA₂DS₂-VASc é usado para:","opcoes":["Avaliar o risco de AVC e a necessidade de anticoagulação","Medir a função renal antes de iniciar o anticoagulante","Avaliar a depressão","Classificar a dor"],"explicacao":"Considera idade, sexo, hipertensão, diabetes, AVC prévio, entre outros."},{"id":5221,"materia":"med","nivel":4,"enunciado":"Em pessoa com tosse crônica que usa enalapril e tem exame físico e raio-X normais, uma conduta razoável é:","opcoes":["Considerar a troca do enalapril por um BRA e reavaliar","Iniciar antibiótico de amplo espectro por 14 dias e repetir o raio-X","Pedir cirurgia","Aumentar a dose do enalapril"],"explicacao":"A tosse do IECA pode demorar semanas para melhorar."},{"id":5222,"materia":"fisio","nivel":0,"enunciado":"A técnica de respiração com lábios franzidos (freno labial) ajuda pessoas com DPOC a:","opcoes":["Reduzir a falta de ar e o aprisionamento de ar","Aumentar a tosse seca, o cansaço e a produção de catarro","Prender a respiração","Engolir melhor"],"explicacao":"A expiração fica mais lenta e controlada."},{"id":5223,"materia":"fisio","nivel":0,"enunciado":"Os músculos do manguito rotador são:","opcoes":["Supraespinal, infraespinal, redondo menor e subescapular","Bíceps, tríceps, deltoide, peitoral maior e grande dorsal","Quadríceps, isquiotibiais e glúteos","Trapézio, romboides e grande dorsal"],"explicacao":"Estabilizam a cabeça do úmero."},{"id":5224,"materia":"fisio","nivel":0,"enunciado":"A hérnia de disco lombar é mais comum entre:","opcoes":["L4-L5 e L5-S1","C1-C2","T1-T2","Cóccix e sacro"],"explicacao":"São os níveis com maior carga mecânica."},{"id":5225,"materia":"fisio","nivel":0,"enunciado":"O bebê costuma sentar sem apoio por volta dos:","opcoes":["6 a 8 meses","2 meses","18 meses","Primeira semana"],"explicacao":"Marco do desenvolvimento motor."},{"id":5226,"materia":"fisio","nivel":0,"enunciado":"A respiração diafragmática ajuda a:","opcoes":["Melhorar a ventilação e reduzir o esforço respiratório","Aumentar a ansiedade","Diminuir a oxigenação","Prender o ar nos pulmões por mais tempo a cada respiração"],"explicacao":"O abdome se expande na inspiração."},{"id":5227,"materia":"fisio","nivel":1,"enunciado":"Após mastectomia, a fisioterapia precoce visa principalmente:","opcoes":["Recuperar a amplitude do ombro e prevenir o linfedema","Imobilizar o braço por meses, sem nenhum movimento do ombro","Aumentar o peso corporal","Tratar a visão"],"explicacao":"Exercícios graduais e orientações de cuidado com o braço."},{"id":5228,"materia":"fisio","nivel":1,"enunciado":"A diástase dos músculos retos abdominais é comum:","opcoes":["Na gestação e no pós-parto","Na infância apenas","Em fraturas de punho","Em entorses de tornozelo graves"],"explicacao":"Exercícios específicos ajudam na recuperação."},{"id":5229,"materia":"fisio","nivel":1,"enunciado":"Na fisioterapia aquática terapêutica, a água costuma ficar aquecida em torno de:","opcoes":["32 °C a 34 °C","10 °C a 15 °C","45 °C a 50 °C","20 °C"],"explicacao":"O calor ajuda no relaxamento muscular."},{"id":5230,"materia":"fisio","nivel":1,"enunciado":"O laser de baixa potência é usado na fisioterapia principalmente para:","opcoes":["Analgesia e estímulo à cicatrização","Cortar tecidos","Esterilizar materiais cirúrgicos e curativos","Medir a força"],"explicacao":"Também chamado de fotobiomodulação."},{"id":5231,"materia":"fisio","nivel":2,"enunciado":"As ondas curtas (diatermia) são contraindicadas em pessoas com:","opcoes":["Implantes metálicos e marca-passo","Dor lombar crônica sem implantes metálicos","Contratura muscular","Rigidez articular"],"explicacao":"O calor profundo pode aquecer o metal."},{"id":5232,"materia":"fisio","nivel":2,"enunciado":"Na síndrome da dor patelofemoral, uma intervenção com boa evidência é:","opcoes":["Fortalecimento do quadríceps e dos músculos do quadril","Repouso absoluto por meses, sem exercícios nem atividade física","Imobilização com gesso","Cirurgia em todos os casos"],"explicacao":"Comum em jovens e corredores."},{"id":5233,"materia":"fisio","nivel":2,"enunciado":"A escala de Tinetti avalia:","opcoes":["O equilíbrio e a marcha, com foco no risco de quedas","A força de preensão das mãos com dinamômetro","A dor","A espasticidade"],"explicacao":"Muito usada em idosos."},{"id":5234,"materia":"fisio","nivel":3,"enunciado":"Na fase aguda de uma lesão, o ultrassom terapêutico, quando usado, deve ser preferencialmente:","opcoes":["Pulsado, para reduzir o efeito térmico","Contínuo e em alta intensidade","Aplicado sobre o útero gravídico para aliviar a dor","Usado sem gel"],"explicacao":"O modo contínuo produz mais calor."},{"id":5235,"materia":"fisio","nivel":3,"enunciado":"No treino de marcha com andador, a sequência habitual é:","opcoes":["Avançar o andador, depois a perna afetada e, por fim, a perna boa","Avançar as duas pernas juntas antes do andador e depois puxá-lo para perto do corpo","Levantar o andador e correr","Arrastar o andador com uma mão só"],"explicacao":"Garante apoio durante o passo."},{"id":5236,"materia":"fisio","nivel":4,"enunciado":"A pressão inspiratória máxima (PImáx), medida pelo manovacuômetro, avalia:","opcoes":["A força dos músculos inspiratórios","A capacidade de caminhar por 6 minutos","A amplitude do ombro","A sensibilidade da pele"],"explicacao":"Útil no treino muscular inspiratório."},{"id":5237,"materia":"enf","nivel":1,"enunciado":"A medida do perímetro cefálico do bebê, registrada na Caderneta da Criança, ajuda a acompanhar:","opcoes":["O crescimento do crânio e do cérebro","A pressão arterial em repouso e depois de caminhar","A visão","O número de dentes"],"explicacao":"Valores muito abaixo ou acima do esperado exigem avaliação."},{"id":5238,"materia":"enf","nivel":2,"enunciado":"Na suspeita de AVC, verificar a glicemia capilar é importante porque:","opcoes":["A hipoglicemia pode causar sinais parecidos com os de um AVC","A glicemia não muda em nada a conduta diante da suspeita de AVC","O AVC sempre causa diabetes","Substitui a tomografia"],"explicacao":"Corrigir a hipoglicemia pode reverter os sintomas."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
